import 'package:flutter/widgets.dart';

/// Single source of truth for every color, type style, spacing, radius, and
/// elevation value used anywhere in the app (Constitution Principle IV; RNF08).
/// Transcribed verbatim from docs/input/prototype/prototype-extract.md §3.
class DesignTokens {
  const DesignTokens._();

  // Colors
  static const Color colorPrimary = Color(0xFF1F3D34);
  static const Color colorPrimaryPressed = Color(0xFF16281F);
  static const Color colorOnPrimary = Color(0xFFF5F1E8);
  static const Color colorAccent = Color(0xFFC98A3E);
  static const Color colorOnAccent = Color(0xFF241C0D);
  static const Color colorSecondary = Color(0xFF7C8B6F);
  static const Color colorSurfaceBg = Color(0xFFF2EFE7);
  static const Color colorSurfaceElevated = Color(0xFFFBF9F4);
  static const Color colorBorder = Color(0xFFE1DACB);
  static const Color colorTextPrimary = Color(0xFF241F19);
  static const Color colorTextSecondary = Color(0xFF6B6255);
  static const Color colorError = Color(0xFFB3402A);
  static const Color colorSuccess = Color(0xFF4C6B4F);
  static const Color colorWarningSync = Color(0xFFC98A3E);
  static const Color colorInfoOffline = Color(0xFF5C7A93);
  static const Color colorChatBubbleUser = Color(0xFFD9DFD3);

  // Typography
  static const String _fontFraunces = 'Fraunces';
  static const String _fontKarla = 'Karla';
  static const String _fontMono = 'IBM Plex Mono';

  static const TextStyle textDisplayLg = TextStyle(
    fontFamily: _fontFraunces,
    fontWeight: FontWeight.w600,
    fontSize: 32,
    height: 38 / 32,
    color: colorTextPrimary,
  );

  static const TextStyle textHeadlineMd = TextStyle(
    fontFamily: _fontFraunces,
    fontWeight: FontWeight.w600,
    fontSize: 24,
    height: 30 / 24,
    color: colorTextPrimary,
  );

  static const TextStyle textTitleLg = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w700,
    fontSize: 20,
    height: 26 / 20,
    color: colorTextPrimary,
  );

  static const TextStyle textTitleSm = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w700,
    fontSize: 16,
    height: 22 / 16,
    color: colorTextPrimary,
  );

  static const TextStyle textBodyLg = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w400,
    fontSize: 16,
    height: 24 / 16,
    color: colorTextPrimary,
  );

  static const TextStyle textBodyMd = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w400,
    fontSize: 14,
    height: 20 / 14,
    color: colorTextPrimary,
  );

  static const TextStyle textLabelMd = TextStyle(
    fontFamily: _fontKarla,
    fontWeight: FontWeight.w500,
    fontSize: 13,
    height: 18 / 13,
    color: colorTextPrimary,
  );

  static const TextStyle textMonoCaption = TextStyle(
    fontFamily: _fontMono,
    fontWeight: FontWeight.w500,
    fontSize: 12,
    height: 16 / 12,
    letterSpacing: 0.2,
    color: colorTextPrimary,
  );

  // Spacing (4 dp grid)
  static const double spacingXs = 4;
  static const double spacingSm = 8;
  static const double spacingMd = 16;
  static const double spacingLg = 24;
  static const double spacingXl = 32;
  static const double spacing2xl = 48;

  // Radii
  static const double radiusSm = 8;
  static const double radiusMd = 16;
  static const double radiusLg = 24;
  static const double radiusFull = 999;

  // Sizes
  static const double sizeLoadingDot = 8;
  static const double sizeLoadingIndicator = 20;
  static const double strokeWidthLoadingIndicator = 2;
  static const double dividerThickness = 1;
  static const double borderWidthFocused = 1.5;
  static const double sizeKeypadTapTarget = 56;
  static const double sizeProgressDot = 10;
  static const double sizeBiometricIconContainer = 96;
  static const double sizeBiometricIcon = 44;

  // Elevation
  static const List<BoxShadow> elevation1 = [
    BoxShadow(
      color: Color.fromRGBO(36, 31, 25, 0.08),
      offset: Offset(0, 1),
      blurRadius: 3,
    ),
  ];

  static const List<BoxShadow> elevation2 = [
    BoxShadow(
      color: Color.fromRGBO(36, 31, 25, 0.14),
      offset: Offset(0, 4),
      blurRadius: 16,
    ),
  ];
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/home/presentation/widgets/app_drawer.dart';
import 'package:flutter/material.dart';

/// Fixed dark-green header (☰ + "Cerne" wordmark) and an empty conversation
/// area, plus a composer bar that is rendered but fully disabled — no fake
/// messages, no RF04 wiring (FR-016; research.md R10). Scaffold's `drawer`
/// gives the ☰ icon its tap target for free (User Story 4).
class HomeChatShellPage extends StatelessWidget {
  const HomeChatShellPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      drawer: const AppDrawer(),
      appBar: AppBar(
        backgroundColor: DesignTokens.colorPrimary,
        foregroundColor: DesignTokens.colorOnPrimary,
        title: Text(
          'Cerne',
          style: DesignTokens.textTitleLg.copyWith(
            color: DesignTokens.colorOnPrimary,
          ),
        ),
      ),
      body: Column(
        children: [
          const Expanded(child: SizedBox.expand()),
          _ComposerBar(),
        ],
      ),
    );
  }
}

class _ComposerBar extends StatelessWidget {
  const _ComposerBar();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        border: Border(top: BorderSide(color: DesignTokens.colorBorder)),
      ),
      child: Row(
        children: [
          Expanded(
            child: TextField(
              enabled: false,
              decoration: const InputDecoration(
                hintText: 'Escreva uma mensagem...',
              ),
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          IconButton(
            onPressed: null,
            icon: const Icon(Icons.send, color: DesignTokens.colorTextSecondary),
          ),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/routing/app_routes.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_bloc.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_event.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_state.dart';
import 'package:cerne/features/vault/presentation/widgets/pin_keypad.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

/// Which entry point opened `VaultPage` — decides the eventual unlocked
/// transition: `go(home)` for [gatekeeper], `pop()` for [relock]
/// (data-model.md State transitions).
enum VaultMode { gatekeeper, relock }

/// The single vault screen (research.md R4) — internally covers first-time
/// PIN setup, the biometric prompt, PIN-entry unlock/fallback, and the
/// biometrics opt-in as `VaultBloc` sub-states.
class VaultPage extends StatefulWidget {
  const VaultPage({required this.mode, super.key});

  final VaultMode mode;

  @override
  State<VaultPage> createState() => _VaultPageState();
}

class _VaultPageState extends State<VaultPage> {
  @override
  void initState() {
    super.initState();
    context.read<VaultBloc>().add(const VaultOpened());
  }

  void _useEmailPassword() => context.push(AppRoutes.login);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: SafeArea(
        child: BlocConsumer<VaultBloc, VaultState>(
          listenWhen: (previous, current) => current is VaultUnlocked,
          listener: (context, state) {
            if (widget.mode == VaultMode.gatekeeper) {
              context.go(AppRoutes.home);
            } else {
              Navigator.of(context).pop();
            }
          },
          builder: (context, state) {
            return switch (state) {
              VaultInitial() => const _LoadingView(),
              VaultPinSetupCreate() => _PinSetupCreateView(state: state),
              VaultPinSetupConfirm() => _PinSetupConfirmView(state: state),
              VaultBiometricOptIn() => const _BiometricOptInView(),
              VaultBiometricPrompting() => _BiometricPromptingView(
                  onUseEmailPassword: _useEmailPassword,
                ),
              VaultPinEntry() => _PinEntryView(
                  state: state,
                  onUseEmailPassword: _useEmailPassword,
                ),
              VaultUnlocked() => const SizedBox.shrink(),
            };
          },
        ),
      ),
    );
  }
}

class _LoadingView extends StatelessWidget {
  const _LoadingView();

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

class _UseEmailPasswordLink extends StatelessWidget {
  const _UseEmailPasswordLink({required this.onPressed});

  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    return TextButton(
      onPressed: onPressed,
      child: const Text('usar e-mail e senha'),
    );
  }
}

class _BiometricPromptingView extends StatelessWidget {
  const _BiometricPromptingView({required this.onUseEmailPassword});

  final VoidCallback onUseEmailPassword;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return Stack(
      children: [
        Center(
          child: Padding(
            padding: const EdgeInsets.symmetric(
              horizontal: DesignTokens.spacingXl,
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                GestureDetector(
                  onTap: () => bloc.add(const BiometricAuthRequested()),
                  child: Container(
                    width: DesignTokens.sizeBiometricIconContainer,
                    height: DesignTokens.sizeBiometricIconContainer,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: DesignTokens.colorSurfaceElevated,
                      border: Border.all(
                        color: DesignTokens.colorBorder,
                        width: DesignTokens.borderWidthFocused,
                      ),
                      boxShadow: DesignTokens.elevation1,
                    ),
                    child: Icon(
                      Icons.fingerprint,
                      size: DesignTokens.sizeBiometricIcon,
                      color: DesignTokens.colorPrimary,
                    ),
                  ),
                ),
                const SizedBox(height: DesignTokens.spacingLg),
                Text('Toque para desbloquear', style: DesignTokens.textTitleLg),
                const SizedBox(height: DesignTokens.spacingSm),
                Text(
                  'Use Face ID ou Touch ID para continuar',
                  textAlign: TextAlign.center,
                  style: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                ),
                const SizedBox(height: DesignTokens.spacingLg),
                TextButton(
                  onPressed: () => bloc.add(const UsePinRequested()),
                  child: Text(
                    'Usar PIN',
                    style: DesignTokens.textMonoCaption.copyWith(
                      color: DesignTokens.colorTextSecondary,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        Positioned(
          left: 0,
          right: 0,
          bottom: DesignTokens.spacing2xl,
          child: Center(
            child: _UseEmailPasswordLink(onPressed: onUseEmailPassword),
          ),
        ),
      ],
    );
  }
}

class _PinEntryView extends StatelessWidget {
  const _PinEntryView({required this.state, required this.onUseEmailPassword});

  final VaultPinEntry state;
  final VoidCallback onUseEmailPassword;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Digite seu PIN', style: DesignTokens.textTitleLg),
          if (state.errorMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            _PinErrorBand(message: state.errorMessage!),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          _UseEmailPasswordLink(onPressed: onUseEmailPassword),
        ],
      ),
    );
  }
}

class _PinErrorBand extends StatelessWidget {
  const _PinErrorBand({required this.message});

  final String message;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(
        horizontal: DesignTokens.spacingMd,
        vertical: DesignTokens.spacingSm,
      ),
      decoration: BoxDecoration(
        color: DesignTokens.colorError.withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(DesignTokens.radiusSm),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            Icons.error_outline,
            size: DesignTokens.spacingMd,
            color: DesignTokens.colorError,
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          Flexible(
            child: Text(
              message,
              style: DesignTokens.textLabelMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _PinSetupCreateView extends StatelessWidget {
  const _PinSetupCreateView({required this.state});

  final VaultPinSetupCreate state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Crie seu PIN', style: DesignTokens.textTitleSm),
          if (state.mismatchMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              state.mismatchMessage!,
              textAlign: TextAlign.center,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
        ],
      ),
    );
  }
}

class _PinSetupConfirmView extends StatelessWidget {
  const _PinSetupConfirmView({required this.state});

  final VaultPinSetupConfirm state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Confirme seu PIN', style: DesignTokens.textTitleSm),
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
        ],
      ),
    );
  }
}

class _BiometricOptInView extends StatelessWidget {
  const _BiometricOptInView();

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            Icons.fingerprint,
            size: DesignTokens.spacing2xl * 2,
            color: DesignTokens.colorPrimary,
          ),
