    when(
      () => remoteDataSource.create(
        content: any(named: 'content'),
        source: any(named: 'source'),
      ),
    ).thenAnswer((_) async => const Left(failure));

    final result = await repository.create(
      content: 'hello',
      source: EntrySource.manual,
    );

