    saveAudioEntryUseCase: saveAudioEntryUseCase,
    photoCaptureRepository: photoCaptureRepository,
    savePhotoEntryUseCase: savePhotoEntryUseCase,
  );

  test('initial state is InsertionModalTexto with an empty draft', () {
