            .thenAnswer((_) async => audioPath);
        when(() => saveAudioEntryUseCase(audioPath)).thenAnswer(
          (_) async => const Left(
            SaveAudioEntryCreationFailed(
              NetworkTimeoutFailure(message: 'timed out', requestId: 'r1'),
